-- +goose Up
-- Запись релиза в журнал (notified_at NULL — бот уведомит админа на старте).
-- +goose StatementBegin
INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.93.0',
  '2026-09-19',
  'Пульт ТВ: «Инфо», плейлисты, ZIP с музыкой, статистика, отправка на ТВ',
  E'У фильмов и сериалов на главной рядом с «＋ В очередь» появилась кнопка «ℹ Инфо»: описание, год, жанры, оценки (Rotten Tomatoes, Metacritic, TVmaze), актёры и размытый постер фоном; оттуда же — «▶ Продолжить» (если уже смотрели), «▶ Смотреть сначала» и список серий. Сведения медиатека находит сама в открытых источниках (IMDb, Wikidata, Википедия, TVmaze) при первом открытии, а в админке их можно поправить или поискать под другим названием.\n\nСвои плейлисты: «＋» у любого трека или «＋ Всю папку в плейлист» — и треки из разных папок собираются в один список. Плейлисты стоят первыми в «Музыке», их можно выбрать под фильм, для слайд-шоу и «Музыки на паузе». Между треками — плавный переход (кнопка «〰 Плавно» на панели музыки).\n\nАльбом музыки можно загрузить ZIP-архивом прямо из админки в браузере: папка в архиве становится альбомом. В админке новая вкладка «Статистика»: сколько смотрели по дням за неделю или месяц и что чаще всего. Таймер сна теперь ещё и на 120 и 180 минут.\n\nИ главное: на странице «Пульт ТВ» в Telegram — «🖼 Фото или видео»: выбираете снимок или ролик в галерее телефона, и он сразу открывается на телевизоре, без медиатеки. «Назад» на пульте или «✕ Убрать» на телефоне закрывает показ.',
  E'Прод: POST /api/v1/tv/cast?room=&name= (tma, только владелец комнаты, приставка должна быть на связи, тело — файл image/* или video/*, до 500 МБ) кладёт файл в DATA_DIR/tvcast под случайным 40-символьным именем и шлёт в комнату {t:"cast", token, kind, name}; GET /api/v1/tv/cast/{token} вне авторизации с Range (ServeContent) и CORS *; POST /api/v1/tv/cast/stop; файлы старше 3 часов стирает фоновая уборка. Пульт (RemoteView.vue) шлёт XHR ради прогресса. Приставка берёт адрес из шины (wss→https, /socket→/cast/), показывает слой #cast поверх всего.\n\nАгент. info.go: GET /api/info?id= — «Инфо» из кэша рядом с постером («Имя.info.json», едет при переименовании и в корзину через общий sidecars()); нет — ищет: подсказки IMDb (id, год, актёры; страница фильма ботам даёт 202) → Wikidata по P345 (жанры P136, актёры P161, дата P577/P580, оценки P444 с критиком P447, одним запросом подписи) → Википедия REST summary по sitelink (ru, иначе en) → TVmaze для сериалов (lookup по IMDb). Кириллица — поиск страницы Википедии и wikibase_item. Промах — сутки. POST /api/admin/info: найти заново (в том числе под другим названием), сохранить руками (edited), очистить. Wikimedia без контакта в User-Agent после пары десятков запросов отвечает «too many requests» — в UA ссылка на репозиторий, и не чаще запроса в 300 мс. imdbPoster и «Инфо» делят imdbFind.\n\nplaylists.go: playlists.json, пути треков (пропавшие молча пропускаются), GET/POST /api/playlists, /{id}, /add (трек или папка целиком, без повторов), /remove, /rename, DELETE; в каталоге поле playlists. upload.go: загрузка частями (POST /api/admin/upload → PUT …?offset= кусками по 768 КБ → finish?target=music-zip|background|cover) — nginx на res-i3 с пределом тела 1 МБ по умолчанию резал загрузку фона из 2.92 (413), куски проходят; 409 с текущим размером — продолжить с места; недокачанное старше суток убирается. ZIP: одна папка — альбом, иначе имя архива; только треки, картинки, .lrc/.cue; __MACOSX, скрытое и «../» пропускаются; имена CP866 без флага UTF-8 декодируются; распаковка во временную скрытую папку и rename; занятое имя — «(2)». stats.go: stats.json, в зачёт — прирост позиции между отметками, если он не больше двух минут и не быстрее хода времени (+10 с); GET /api/stats?days=.\n\nСтраница: второй <audio> и onAudio() — события только текущего элемента; переход за 4 с до конца, пауза отменяет его; в режиме «один трек» и на последнем треке «один раз» перехода нет. Плейлисты: плитки, экран, «＋»/«✕» у трека, выбор плейлиста окном; tracksOf() для папки и плейлиста — в выборе музыки, слайд-шоу и «Музыке на паузе». «Инфо» — экран vstack kind info с размытым постером. Админка: карточка ZIP во вкладке «Медиатека», «ℹ» у строки, вкладка «Статистика» со столбцами; файлы фона и обложек тоже частями. Объявления, которые читает renderMusicModes() при загрузке, перенесены выше — иначе скрипт падал бы (поймано до выкладки, как в 2.90).\n\nПроверено: music_test.go (плейлисты, ZIP частями с мусором, «../» и повтором имени, CP866, статистика, описание рядом с постером при переименовании и в корзине), info_live_test.go на живом интернете (INFO_LIVE=1: Fauda, The Gentlemen, «Джентльмены», Legion, 99 francs), локальный бэкенд с сырым веб-сокетом приставки (отправка, чужая комната 404, не фото 400, файл без авторизации, Range 206, неверный токен 404, стоп), страница в браузере на локальном агенте, после выкладки — «Инфо» для Legion и «Джентльменов» с самого res-i3.'
);
